export function HeightDemo({
  mode = "{{mode}}",
  value = {{value}},
  background = "{{background}}",
}) {
  const boxHeight = mode === "auto" ? "auto" : `${value}${mode}`;
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="An element's height set in pixels, percent of its container, or auto to fit content">
      <div style={{ height: 200, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box", display: "flex" }}>
        <div style={{ width: 120, background, borderRadius: 6, display: "flex", alignItems: "flex-start", justifyContent: "center",
          padding: mode === "auto" ? "14px 8px" : "8px 0 0", fontWeight: 700, height: boxHeight }}>
          box
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>height: {value}{mode} (container is 200px tall)</p>
    </div>
  );
}
